export const STAGES = [{ id: "bs", label: "Basics" }, { id: "un", label: "Units" }, { id: "sp", label: "Specs" }, { id: "gb", label: "Gasoline blending" }, { id: "db", label: "Diesel blending" }, { id: "rn", label: "Renewables" }, { id: "ec", label: "Economics" }];
export const MATHS = [{"id":"RF-01","lv":"bs","d":1,"area":"Distillation","q":"What does the crude distillation unit do?","o":["Cracks heavy molecules into lighter ones","Separates crude into cuts by boiling range","Removes sulphur from the crude","Blends the finished products"],"a":[1],"s":1,"x":"Nothing is converted in the crude unit: a furnace and a tall column simply sort the crude into cuts, gases to residue, by boiling point."},{"id":"RF-02","lv":"bs","d":1,"area":"Distillation","q":"Which of these cuts boils highest, and so comes off the bottom of the crude column?","o":["LPG","Naphtha","Kerosene","Atmospheric residue"],"a":[3],"s":1,"x":"Residue is what hasn't boiled at the column's bottom temperature; it goes to the vacuum unit or to fuel oil."},{"id":"RF-03","lv":"bs","d":2,"area":"Distillation","q":"Why is the atmospheric residue distilled under vacuum rather than simply heated further?","o":["Vacuum makes the column cheaper to build","At the temperature it would need at atmospheric pressure it would crack and coke","Vacuum removes its sulphur","The residue contains water that must be boiled off"],"a":[1],"s":1,"x":"Lowering the pressure lowers the boiling points, so vacuum gas oil can be lifted out of the residue at a temperature where it doesn't crack."},{"id":"RF-04","lv":"bs","d":1,"area":"Crudes","q":"A \"sweet\" crude is one with","o":["Low sulphur","High API gravity","Low acidity","A high naphtha yield"],"a":[0],"s":1,"x":"Sweet means low in sulphur, typically under 0.5%; sour crudes carry more and need more hydrotreating."},{"id":"RF-05","lv":"bs","d":2,"area":"Crudes","q":"A crude with a higher API gravity is","o":["Heavier and denser","Lighter and less dense","More acidic","Richer in sulphur"],"a":[1],"s":1,"x":"API gravity runs the other way to density: 40° API is light, 22° is heavy. Light crudes give more naphtha and distillate."},{"id":"RF-06","lv":"bs","d":2,"area":"Crudes","q":"Which crude gives the most naphtha per barrel?","o":["Maya, API 22","Arab Heavy, API 28","Urals, API 31","WTI, API 40"],"a":[3],"s":1,"x":"The lighter the crude, the more of it boils in the naphtha range; a heavy crude is mostly residue."},{"id":"RF-07","lv":"bs","d":3,"area":"Configuration","q":"What does a hydroskimming refinery lack?","o":["A crude distillation unit","A catalytic reformer","Conversion units such as an FCC, hydrocracker or coker","Hydrotreaters"],"a":[2],"s":1,"x":"Hydroskimming is distillation, treating and reforming only: its residue goes to fuel oil, which is why its margins are thin."},{"id":"RF-08","lv":"bs","d":2,"area":"Products","q":"Which product usually sells for the least per barrel?","o":["Jet fuel","Diesel","High-sulphur fuel oil","Gasoline"],"a":[2],"s":1,"x":"Fuel oil, especially high-sulphur fuel oil since IMO 2020, prices below crude; that discount is what conversion units exist to escape."},{"id":"RF-09","lv":"bs","d":2,"area":"Products","q":"\"The bottom of the barrel\" refers to","o":["LPG and fuel gas","Light naphtha","Vacuum residue","Kerosene"],"a":[2],"s":1,"x":"Vacuum residue is the heaviest material a refinery handles: coker feed, visbreaker feed, bitumen, or fuel oil."},{"id":"RF-10","lv":"bs","d":3,"area":"Operations","q":"A refinery turnaround is","o":["A reversal of the crude slate","A planned shutdown for inspection and maintenance, every few years","The switch from summer to winter gasoline","A change of ownership"],"a":[1],"s":1,"x":"Units run for four to six years between turnarounds, when they are shut, opened, inspected and repaired over several weeks."},{"id":"RF-11","lv":"un","d":2,"area":"Reforming","q":"Which unit produces hydrogen as a by-product?","o":["Catalytic reformer","Hydrocracker","Diesel hydrotreater","FCC"],"a":[0],"s":1,"x":"Dehydrogenating naphtha into aromatics releases hydrogen, about 1,000 scf a barrel: the reformer is the refinery's own hydrogen supply."},{"id":"RF-12","lv":"un","d":2,"area":"Reforming","q":"What feeds the catalytic reformer?","o":["Light naphtha (C5–C6)","Hydrotreated heavy naphtha (C7–C10)","Vacuum gas oil","Kerosene"],"a":[1],"s":1,"x":"Heavy naphtha has the ring-forming molecules; it is hydrotreated first because sulphur poisons the platinum."},{"id":"RF-13","lv":"un","d":2,"area":"Reforming","q":"What is reformate prized for?","o":["Its cetane","Its high octane","Its low density","Its low aromatics"],"a":[1],"s":1,"x":"Reformate is mostly aromatics with RON around 100: the backbone of the gasoline pool's octane."},{"id":"RF-14","lv":"un","d":3,"area":"Octane","q":"What feeds an isomerisation unit?","o":["Heavy naphtha","FCC naphtha","Light naphtha (C5–C6)","Reformate"],"a":[2],"s":1,"x":"Straight-chain pentane and hexane are isomerised into their branched forms, lifting octane from about 70 to the high 80s."},{"id":"RF-15","lv":"un","d":2,"area":"Cracking","q":"What is the FCC's main product?","o":["Gasoline-range naphtha","Diesel","Petroleum coke","Hydrogen"],"a":[0],"s":1,"x":"About half of the feed becomes cracked naphtha: high octane but sour, so it needs a post-treater."},{"id":"RF-16","lv":"un","d":4,"area":"Cracking","q":"What catalyst does the FCC use?","o":["Platinum on alumina","A fluidised zeolite powder","Hydrofluoric acid","Nickel"],"a":[1],"s":1,"x":"A fine zeolite catalyst circulates as a fluid between the riser, where it cracks the feed, and the regenerator, where its coke is burned off."},{"id":"RF-17","lv":"un","d":3,"area":"Cracking","q":"What happens to the coke that forms on the FCC catalyst?","o":["It is sold as petroleum coke","It is burned off in the regenerator, heating the catalyst for the next pass","It is hydrotreated into diesel","It is sent to the coker"],"a":[1],"s":1,"x":"The burn-off supplies the heat the cracking reactions need: an FCC in heat balance needs no external fuel."},{"id":"RF-18","lv":"un","d":3,"area":"Cracking","q":"Light cycle oil (LCO) is","o":["A lubricant base oil","A gas oil from the FCC with poor cetane","The FCC's naphtha fraction","Hydrocracker diesel"],"a":[1],"s":1,"x":"LCO is aromatic cracked gas oil, cetane in the 20s: it treats to 10 ppm but drags the diesel pool's cetane down."},{"id":"RF-19","lv":"un","d":2,"area":"Cracking","q":"What does a hydrocracker mainly make?","o":["Gasoline","Jet fuel and diesel","Petroleum coke","Propylene"],"a":[1],"s":1,"x":"Under high hydrogen pressure, vacuum gas oil cracks into clean middle distillates: the hydrocracker is the distillate refinery's conversion unit."},{"id":"RF-20","lv":"un","d":2,"area":"Hydrogen","q":"Which of these consumes hydrogen?","o":["Catalytic reformer","FCC","Hydrocracker","Vacuum distillation"],"a":[2],"s":1,"x":"The hydrocracker is the largest hydrogen consumer in most refineries, around 2,000 scf a barrel; the reformer makes hydrogen and the FCC needs none."},{"id":"RF-21","lv":"un","d":3,"area":"Octane","q":"Which unit uses a strong acid as its catalyst?","o":["Alkylation","Isomerisation","Reforming","Hydrocracking"],"a":[0],"s":1,"x":"Alkylation runs over hydrofluoric or sulphuric acid, which is why alkylation units are the most hazardous in a refinery."},{"id":"RF-22","lv":"un","d":3,"area":"Octane","q":"What does the alkylation unit feed on?","o":["Heavy naphtha","Isobutane and C3–C4 olefins","Vacuum residue","Kerosene"],"a":[1],"s":1,"x":"The FCC's butenes and propylene are joined to isobutane into branched C8 paraffins: alkylate."},{"id":"RF-23","lv":"un","d":4,"area":"Octane","q":"Why is alkylate the most valued gasoline blendstock?","o":["It has the highest energy content","High octane with low vapour pressure, no sulphur and no aromatics","It is the cheapest to make","It can be sold as jet fuel"],"a":[1],"s":1,"x":"Octane around 95 without the aromatics of reformate or the olefins of FCC naphtha, and a low RVP that leaves room for butane."},{"id":"RF-24","lv":"un","d":1,"area":"Coking","q":"Which unit makes a solid product?","o":["Delayed coker","FCC","Hydrocracker","Reformer"],"a":[0],"s":1,"x":"The coker leaves petroleum coke in its drums, cut out with water jets once a drum is full."},{"id":"RF-25","lv":"un","d":2,"area":"Coking","q":"What is the delayed coker for?","o":["Making gasoline from naphtha","Converting vacuum residue into lighter products and coke","Removing sulphur from diesel","Making hydrogen"],"a":[1],"s":1,"x":"The deepest conversion step: residue in, nothing heavier than gas oil out, and the carbon left as coke."},{"id":"RF-26","lv":"un","d":4,"area":"Coking","q":"What is a visbreaker for?","o":["Lifting the octane of naphtha","Reducing the viscosity of residue so less cutter stock is needed for fuel oil","Making lubricants","Recovering sulphur"],"a":[1],"s":1,"x":"A mild thermal cracker: it thins the residue so that less valuable gas oil has to be blended in to meet fuel oil's viscosity."},{"id":"RF-27","lv":"un","d":3,"area":"Sulphur","q":"What does a Claus unit do?","o":["Converts hydrogen sulphide into elemental sulphur","Removes sulphur from diesel","Makes sulphuric acid","Scrubs SO2 from flue gas"],"a":[0],"s":1,"x":"A third of the H2S is burned to SO2, which reacts with the rest to give sulphur and water: the sulphur recovery unit."},{"id":"RF-28","lv":"un","d":3,"area":"Hydrogen","q":"What feeds a hydrogen plant (steam methane reformer)?","o":["Naphtha and oxygen","Natural gas and steam","Vacuum residue","Fuel oil"],"a":[1],"s":1,"x":"Methane and steam over nickel at about 900 °C give hydrogen and carbon monoxide, then more hydrogen by the shift reaction."},{"id":"RF-29","lv":"un","d":4,"area":"Sulphur","q":"What does an amine unit do?","o":["Absorbs hydrogen sulphide and CO2 from gas streams","Makes ammonia","Neutralises acid in crude","Dries LPG"],"a":[0],"s":1,"x":"Amine solutions scrub H2S out of the refinery's gas streams and release it, concentrated, to the sulphur plant."},{"id":"RF-30","lv":"un","d":5,"area":"Treating","q":"Merox treating is used to","o":["Remove mercaptans (sweeten) kerosene and LPG","Crack residue","Lift octane","Recover hydrogen"],"a":[0],"s":1,"x":"Mercaptan oxidation turns smelly, corrosive mercaptans into disulphides; a Merox unit may be all sweet kerosene needs to make jet."},{"id":"RF-31","lv":"un","d":3,"area":"Hydrogen","q":"In most refineries the largest consumer of hydrogen is","o":["The reformer","The hydrocracker","The crude unit","The FCC"],"a":[1],"s":1,"x":"At around 2,000 scf a barrel, the hydrocracker dwarfs the hydrotreaters; an HVO unit is the other big consumer."},{"id":"RF-32","lv":"un","d":3,"area":"Treating","q":"Why is naphtha hydrotreated before the reformer?","o":["To raise its octane","Because sulphur poisons the reformer's platinum catalyst","To remove water","To lower its density"],"a":[1],"s":1,"x":"A few ppm of sulphur deactivates the platinum; the hydrotreater brings it to under 1 ppm."},{"id":"RF-33","lv":"un","d":2,"area":"Treating","q":"What does a diesel hydrotreater mainly remove?","o":["Sulphur","Water","Wax","Octane"],"a":[0],"s":1,"x":"Sulphur comes out as hydrogen sulphide, taking straight-run gas oil from around 1% to 10 ppm; some nitrogen and aromatics go too."},{"id":"RF-34","lv":"un","d":4,"area":"Reforming","q":"The reformer's catalyst is based on","o":["Nickel","Platinum, often with rhenium or tin","Zeolite","Sulphuric acid"],"a":[1],"s":1,"x":"Platinum on chlorided alumina, promoted with rhenium in semi-regenerative units and tin in continuous ones."},{"id":"RF-35","lv":"un","d":4,"area":"Reforming","q":"CCR stands for","o":["Catalytic cracking reactor","Continuous catalyst regeneration","Crude cut ratio","Coker conversion rate"],"a":[1],"s":1,"x":"In a CCR reformer the catalyst circulates slowly to a regenerator, so the unit runs at high severity without shutting down to regenerate."},{"id":"RF-36","lv":"un","d":4,"area":"Cracking","q":"Why does a hydrocracker make more than a barrel of product from a barrel of feed?","o":["Water is added","Hydrogen is added to the molecules, raising volume","The products are lighter and expand when heated","It doesn't; the volume shrinks"],"a":[1],"s":1,"x":"Hydrogen addition lowers density: the products take up about 8% more volume than the feed."},{"id":"RF-37","lv":"un","d":3,"area":"Petrochemicals","q":"The FCC's propylene is mostly sold to","o":["Power stations","Petrochemical plants, for polypropylene","Ships as bunker fuel","Refineries as hydrogen"],"a":[1],"s":1,"x":"Refinery-grade propylene, purified to polymer grade, feeds polypropylene; FCCs are a major propylene source."},{"id":"RF-38","lv":"un","d":3,"area":"Petrochemicals","q":"A steam cracker makes ethylene mainly from","o":["Vacuum residue","Naphtha or ethane","Reformate","Petroleum coke"],"a":[1],"s":1,"x":"Naphtha in Europe and Asia, ethane in the US: cracked with steam at over 800 °C into ethylene, propylene and butadiene."},{"id":"RF-39","lv":"un","d":3,"area":"Residue","q":"Bitumen is made from","o":["Vacuum residue of asphaltic crudes","Light naphtha","Kerosene","FCC slurry"],"a":[0],"s":1,"x":"Air-blown vacuum residue from heavy, naphthenic crudes; Maya or Venezuelan crudes make good bitumen, Brent does not."},{"id":"RF-40","lv":"un","d":7,"area":"Lubricants","q":"Lubricant base oils are made from","o":["Vacuum gas oil, by solvent extraction and dewaxing or hydroprocessing","Light naphtha","Atmospheric residue, blown with air","Reformate"],"a":[0],"s":1,"x":"Group I base oils come from solvent-refined vacuum distillates; Group II and III from hydrocracked and isodewaxed stocks."},{"id":"RF-41","lv":"un","d":4,"area":"Hydrogen","q":"Which two units produce hydrogen sulphide?","o":["Diesel hydrotreater","Catalytic reformer","Naphtha hydrotreater","Isomerisation unit"],"a":[0,2],"s":2,"x":"Every hydrotreater strips sulphur out as H2S. The reformer and the isomerisation unit run on already-treated feed."},{"id":"RF-42","lv":"un","d":4,"area":"Cracking","q":"Which two are conversion units?","o":["Naphtha hydrotreater","FCC","Delayed coker","Sulphur recovery unit"],"a":[1,2],"s":2,"x":"Conversion units change molecular size: the FCC and the coker crack heavy material into lighter products. Treaters and the sulphur plant don't."},{"id":"RF-43","lv":"un","d":5,"area":"Hydrogen","q":"Which two consume large amounts of hydrogen?","o":["Hydrocracker","Catalytic reformer","HVO unit","FCC"],"a":[0,2],"s":2,"x":"The hydrocracker (about 2,000 scf a barrel) and an HVO unit (about 3,000) are the big consumers; the reformer makes hydrogen and the FCC uses none."},{"id":"RF-44","lv":"sp","d":2,"area":"Specs","q":"The sulphur limit for road diesel and petrol in the EU is","o":["10 ppm","50 ppm","350 ppm","0.5%"],"a":[0],"s":1,"x":"10 ppm since 2009, the end of a path from 2,000 ppm in the early 1990s."},{"id":"RF-45","lv":"sp","d":4,"area":"Specs","q":"EN 590 diesel requires a cetane number of at least","o":["40","45","51","60"],"a":[2],"s":1,"x":"51; HVO at 70-plus and hydrocracker diesel in the mid-50s lift a pool, LCO in the 20s sinks it."},{"id":"RF-46","lv":"sp","d":2,"area":"Specs","q":"Premium unleaded petrol in Europe has a research octane number of","o":["87","91","95","100"],"a":[2],"s":1,"x":"RON 95 (Eurosuper); 98 for super plus."},{"id":"RF-47","lv":"sp","d":5,"area":"Blending","q":"Which gasoline blendstock has the lowest vapour pressure?","o":["Butane","Alkylate","Light naphtha","Reformate"],"a":[1],"s":1,"x":"Alkylate's low RVP is one reason it is valued: it leaves room in the pool for cheap, high-RVP butane."},{"id":"RF-48","lv":"sp","d":4,"area":"Blending","q":"Ethanol's blending octane is about","o":["70","85","95","108"],"a":[3],"s":1,"x":"Around 108 RON: ethanol lifts a gasoline pool's octane as well as meeting the biofuel mandate."},{"id":"RF-49","lv":"sp","d":3,"area":"Specs","q":"The maximum FAME content of EN 590 diesel (B7) is","o":["5%","7%","10%","20%"],"a":[1],"s":1,"x":"7% by volume; higher blends need engine approval or a different standard."},{"id":"RF-50","lv":"sp","d":4,"area":"Blending","q":"Which stream drags a diesel pool's cetane down the most?","o":["Hydrocracker diesel","HVO","Light cycle oil","Straight-run gas oil"],"a":[2],"s":1,"x":"LCO's aromatic structure gives it cetane in the 20s against 50 or more for the others."},{"id":"RF-51","lv":"sp","d":5,"area":"Specs","q":"Which of these is a jet fuel specification, not a diesel one?","o":["Cetane number","Freeze point","Sulphur content","Density"],"a":[1],"s":1,"x":"Jet is specified on freeze point, smoke point and flash point among others; cetane is a diesel property."},{"id":"RF-52","lv":"sp","d":3,"area":"Specs","q":"IMO 2020 cut the sulphur limit for marine fuel to","o":["3.5%","1.0%","0.5%","0.1%"],"a":[2],"s":1,"x":"0.5% globally from January 2020, 0.1% in emission control areas; ships with scrubbers may still burn 3.5% fuel."},{"id":"RF-53","lv":"sp","d":6,"area":"Blending","q":"How do octane numbers blend by volume?","o":["Exactly linearly","Approximately linearly, with some non-linear bonus or penalty","They don't blend; the pool takes the lowest","They blend by weight only"],"a":[1],"s":1,"x":"Linear by volume is close enough for a first estimate; refiners use blending octane numbers to capture the non-linearities."},{"id":"RF-54","lv":"sp","d":4,"area":"Blending","q":"Which two are strong octane contributors to a gasoline pool?","o":["Reformate","Alkylate","Light straight-run naphtha","Light cycle oil"],"a":[0,1],"s":2,"x":"Reformate at around 100 RON and alkylate at around 95; light naphtha sits near 70, and LCO is a diesel stream."},{"id":"RF-55","lv":"sp","d":3,"area":"Products","q":"Off-spec gasoline, below RON 95, typically ends up sold as","o":["Jet fuel","Petrochemical naphtha","Diesel","Bitumen"],"a":[1],"s":1,"x":"Naphtha prices below gasoline and is sold to steam crackers; failing the gasoline spec costs the difference."},{"id":"RF-56","lv":"rn","d":2,"area":"HVO","q":"HVO (hydrotreated vegetable oil) is made by","o":["Fermenting sugars","Hydrotreating vegetable oils and fats into paraffins","Reacting oils with methanol","Gasifying wood"],"a":[1],"s":1,"x":"Hydrogen removes the oxygen and saturates the chains: the product is paraffinic renewable diesel with cetane in the 70s."},{"id":"RF-57","lv":"rn","d":2,"area":"FAME","q":"FAME (biodiesel) is made by","o":["Hydrotreating","Transesterification of oils with methanol, giving glycerol as a by-product","Distilling vegetable oil","Pyrolysis"],"a":[1],"s":1,"x":"Triglycerides react with methanol over a base catalyst to give fatty acid methyl esters and glycerol."},{"id":"RF-58","lv":"rn","d":4,"area":"HVO","q":"Which renewable diesel can be used neat in a diesel engine without a blend limit?","o":["FAME","HVO","Ethanol","Glycerol"],"a":[1],"s":1,"x":"HVO meets EN 15940 for paraffinic diesel and is approved neat by many manufacturers; FAME is limited to 7% in EN 590."},{"id":"RF-59","lv":"rn","d":4,"area":"SAF","q":"HEFA jet fuel is","o":["Ethanol converted to jet","Hydroprocessed esters and fatty acids: the HVO route taken to kerosene","Jet made from coal","Synthetic jet from CO2 and hydrogen"],"a":[1],"s":1,"x":"The same hydrotreating of fats, with isomerisation to meet jet's freeze point: the main sustainable aviation fuel route today."},{"id":"RF-60","lv":"rn","d":5,"area":"Co-processing","q":"Co-processing means","o":["Running two crudes at once","Feeding renewable oils into existing refinery units alongside fossil streams","Blending FAME into diesel","Processing crude at two refineries"],"a":[1],"s":1,"x":"Vegetable oils or pyrolysis oils go into an existing hydrotreater or FCC with the fossil feed; the renewable share of the product is tracked by mass balance."},{"id":"RF-61","lv":"rn","d":5,"area":"HVO","q":"Which are by-products of an HVO unit?","o":["Propane and naphtha","Glycerol","Petroleum coke","Hydrogen"],"a":[0],"s":1,"x":"Deoxygenation makes water and CO2, the glycerol backbone becomes propane, and a little naphtha cracks off; glycerol is FAME's by-product, not HVO's."},{"id":"RF-62","lv":"rn","d":5,"area":"HVO","q":"Why does an HVO unit use far more hydrogen than a diesel hydrotreater?","o":["Vegetable oil contains sulphur","The oxygen in the fats has to be removed and the chains saturated","The feed is heavier","It runs at lower pressure"],"a":[1],"s":1,"x":"Triglycerides are about 11% oxygen by weight; removing it as water and CO2, and saturating the double bonds, takes around 3,000 scf a barrel."},{"id":"RF-63","lv":"rn","d":6,"area":"Policy","q":"Under RED, the value an HVO barrel earns on top of its diesel price comes from","o":["A tax on fossil diesel","The compliance ticket or quota credit it generates for an obligated supplier","A government price floor","Its higher energy content"],"a":[1],"s":1,"x":"Blending obligations are met with certificates or quota transfers; the renewable barrel carries that value, which is why HVO prices near double fossil diesel."},{"id":"RF-64","lv":"ec","d":4,"area":"Margins","q":"A 3-2-1 crack spread values","o":["Three barrels of crude against two of gasoline and one of distillate","Three units of conversion per barrel","The spread between Brent and WTI","Two barrels of fuel oil against one of jet"],"a":[0],"s":1,"x":"A rough refining margin: the price of 2 gasoline plus 1 distillate, less 3 crude, per barrel."},{"id":"RF-65","lv":"ec","d":5,"area":"Configuration","q":"The Nelson complexity index measures","o":["A refinery's crude capacity","The cost of its conversion units relative to its crude unit, as a measure of complexity","Its sulphur output","Its energy efficiency"],"a":[1],"s":1,"x":"Each unit is weighted by its cost per barrel relative to distillation; a hydroskimmer scores about 3, a coking refinery 10 or more."},{"id":"RF-66","lv":"ec","d":6,"area":"Margins","q":"Which refinery gains most when the discount of heavy sour crude to light sweet widens?","o":["A hydroskimmer","A coking refinery","A topping plant","A lube plant"],"a":[1],"s":1,"x":"Deep conversion refineries can run the cheap heavy crude and still make clean products; simple refineries cannot."},{"id":"RF-67","lv":"ec","d":5,"area":"Margins","q":"Why do simple refineries suffer when fuel oil's discount to crude widens?","o":["They can't buy crude","Their residue sells as fuel oil, so more of each barrel sells below cost","They make too much gasoline","Their jet fuel is off spec"],"a":[1],"s":1,"x":"Without conversion, a third or more of the barrel ends up as fuel oil; when that prices far below crude, the margin goes negative."},{"id":"RF-68","lv":"ec","d":5,"area":"Configuration","q":"Which product's demand drove European refineries to add hydrocrackers?","o":["Gasoline","Diesel","Fuel oil","LPG"],"a":[1],"s":1,"x":"Europe's dieselisation left refineries long gasoline and short diesel; hydrocrackers make the distillate the market wanted."},{"id":"RF-69","lv":"ec","d":6,"area":"Operations","q":"Which crude property most increases hydrogen consumption in treating?","o":["API gravity","Sulphur (and aromatics) content","Wax content","Viscosity"],"a":[1],"s":1,"x":"Every sulphur atom removed takes hydrogen, and sour crudes are also more aromatic; a sour slate can double a refinery's hydrogen need."},{"id":"RF-70","lv":"ec","d":5,"area":"Configuration","q":"Which combination adds most value to a heavy sour crude?","o":["A reformer and an isomerisation unit","A coker and a hydrocracker with a hydrogen plant","A kerosene treater","A visbreaker alone"],"a":[1],"s":1,"x":"Deep conversion: the coker takes the residue apart and the hydrocracker turns the gas oils into clean distillate."},{"id":"RF-71","lv":"ec","d":4,"area":"Operations","q":"Why does a refinery send every barrel of kerosene it can to the jet pool?","o":["Jet fuel is easier to make than diesel","Jet usually prices above diesel","Kerosene can't be made into diesel","Jet needs no treating"],"a":[1],"s":1,"x":"Jet typically carries a premium over diesel; kerosene that doesn't make jet drops into the diesel pool at the lower price."},{"id":"RF-72","lv":"gb","d":3,"area":"Molecules","q":"Alkylate is made of","o":["Saturated, branched-chain alkanes (isoparaffins)","Aromatic rings","Olefins","Naphthenes"],"a":[0],"s":1,"x":"Trimethylpentanes and their relatives: fully saturated and branched, which is why alkylate is stable, clean-burning and high in octane."},{"id":"RF-73","lv":"gb","d":3,"area":"Molecules","q":"Reformate's octane comes mainly from","o":["Isoparaffins","Aromatics: benzene, toluene and xylenes","Olefins","Cycloalkanes"],"a":[1],"s":1,"x":"The reformer turns naphthenes and paraffins into aromatic rings; reformate is 60–75% aromatics by volume."},{"id":"RF-74","lv":"gb","d":4,"area":"Molecules","q":"Which aromatics dominate a road-gasoline reformate, and why?","o":["Benzene, because it has the highest octane","Toluene and xylenes, because benzene is capped at 1% for toxicity","Naphthalene, because it is heaviest","Styrene, because it is cheapest"],"a":[1],"s":1,"x":"EN 228 limits benzene to 1% by volume as a carcinogen, so refineries keep benzene precursors out of the reformer feed or remove benzene afterwards; C7 and C8 aromatics carry the octane."},{"id":"RF-75","lv":"gb","d":5,"area":"Reforming","q":"In the catalytic reformer, naphthenes (cycloalkanes) become","o":["Olefins","Aromatics, by dehydrogenation","Straight-chain paraffins","Coke only"],"a":[1],"s":1,"x":"Cyclohexane loses hydrogen over platinum to become benzene, methylcyclohexane becomes toluene: fast, endothermic, and the reformer's main octane reaction."},{"id":"RF-76","lv":"gb","d":5,"area":"Reforming","q":"Which reformer reaction is slowest and hardest, yet essential for octane?","o":["Naphthene dehydrogenation","Paraffin isomerisation","Paraffin dehydrocyclisation into aromatics","Hydrocracking to gas"],"a":[2],"s":1,"x":"Closing a straight chain into a ring and then dehydrogenating it needs the highest severity; hydrocracking is the unwanted side reaction that loses liquid to gas."},{"id":"RF-77","lv":"gb","d":5,"area":"Reforming","q":"Why does the reformer not make olefins?","o":["Olefins boil too high","The hydrogen partial pressure and the catalyst saturate them; olefins would foul the catalyst with coke","Olefins are removed by the hydrotreater afterwards","It does: reformate is 20% olefins"],"a":[1],"s":1,"x":"Reformers run under hydrogen; any olefin formed is hydrogenated or ends up as coke on the platinum, so reformate is essentially olefin-free."},{"id":"RF-78","lv":"gb","d":4,"area":"Reforming","q":"Raising the reformer's severity","o":["Raises reformate octane but lowers the C5+ liquid yield","Raises both octane and yield","Lowers octane and raises yield","Changes nothing but hydrogen"],"a":[0],"s":1,"x":"More severe conditions make more aromatics and more hydrogen but crack more feed to gas: an octane-barrel trade-off the refinery optimises against the gasoline pool's needs."},{"id":"RF-79","lv":"gb","d":5,"area":"Reforming","q":"How do refineries keep benzene out of reformate at the source?","o":["By adding water to the reactor","By fractionating C6 precursors (cyclohexane, methylcyclopentane) out of the feed and sending them to isomerisation","By running the reformer colder","By blending in alkylate"],"a":[1],"s":1,"x":"Raising the feed's initial boiling point above the C6 naphthenes removes the molecules that would become benzene; they go to the isomerisation unit instead, where they stay saturated."},{"id":"RF-80","lv":"gb","d":5,"area":"Alkylation","q":"The alkylation reaction joins","o":["Two olefins","Isobutane with a light olefin such as butene or isobutylene","n-Butane with propane","Benzene with ethylene"],"a":[1],"s":1,"x":"An addition reaction over a liquid acid: the branched alkane isobutane adds to a C3–C5 olefin to make a branched C7–C9 alkane, mostly trimethylpentanes."},{"id":"RF-81","lv":"gb","d":5,"area":"Alkylation","q":"Why is n-butane useless as an alkylation feed?","o":["It is too heavy","Straight-chain butane has no tertiary carbon to form the carbocation the acid chemistry needs","It poisons the acid","It boils too low"],"a":[1],"s":1,"x":"Only isobutane, with its branched tertiary hydrogen, forms the stable carbocation that adds to the olefin; n-butane passes through unreacted and is drawn off."},{"id":"RF-82","lv":"gb","d":6,"area":"Alkylation","q":"Why do alkylation units run with a large excess of isobutane over olefin?","o":["To cool the reactor","To stop olefins reacting with each other into polymer and heavy, low-octane ends","Because isobutane is cheaper","To raise the vapour pressure"],"a":[1],"s":1,"x":"Isobutane-to-olefin ratios of 8–10 keep olefin concentrations low; otherwise olefins polymerise, consuming acid and making heavy, dark alkylate."},{"id":"RF-83","lv":"gb","d":4,"area":"Alkylation","q":"Isooctane, the reference fuel defining 100 RON, is","o":["n-Octane","2,2,4-Trimethylpentane, a branched C8 alkane","Benzene","Cyclooctane"],"a":[1],"s":1,"x":"The octane scale runs from n-heptane (0) to 2,2,4-trimethylpentane (100), exactly the kind of molecule alkylation makes."},{"id":"RF-84","lv":"gb","d":4,"area":"Isomerisation","q":"Isomerisation turns","o":["Straight-chain C5 and C6 alkanes into their branched isomers","Olefins into alkanes","Aromatics into naphthenes","Naphtha into LPG"],"a":[0],"s":1,"x":"n-Pentane becomes isopentane, n-hexane becomes methylpentanes and dimethylbutanes: same molecules rearranged, octane up from about 70 to the high 80s."},{"id":"RF-85","lv":"gb","d":6,"area":"Isomerisation","q":"Why does a once-through isomerisation unit stop at about RON 83 while a recycle unit reaches 88–90?","o":["Recycle runs hotter","The reaction reaches equilibrium between straight and branched isomers; recycling the unconverted normals through a separator pushes the product further","Recycle uses a different catalyst","Once-through units lose octane to hydrocracking"],"a":[1],"s":1,"x":"Isomerisation is equilibrium-limited at reactor temperature; separating and recycling n-paraffins (by deisohexaniser or molecular sieve) lifts the product's branched share."},{"id":"RF-86","lv":"gb","d":4,"area":"Octane","q":"FCC gasoline has good octane and poor stability because it is rich in","o":["Aromatics","Olefins (alkenes)","Naphthenes","Isoparaffins"],"a":[1],"s":1,"x":"Cracking makes olefins, 20–40% of FCC naphtha: they bring octane but react with oxygen to form gums that foul injectors and intake valves."},{"id":"RF-87","lv":"gb","d":5,"area":"Octane","q":"Hydrotreating FCC naphtha to remove sulphur costs octane because","o":["The catalyst cracks it","Hydrogen saturates the olefins that carry the octane","It removes aromatics","It raises the vapour pressure"],"a":[1],"s":1,"x":"Conventional hydrotreating saturates olefins into lower-octane paraffins; selective post-treaters are designed to remove sulphur while sparing the olefins, at a cost of a point or two rather than ten."},{"id":"RF-88","lv":"gb","d":5,"area":"Octane","q":"Octane sensitivity is","o":["The octane change with temperature","RON minus MON","The octane of the lightest fraction","The spread between summer and winter grades"],"a":[1],"s":1,"x":"RON is measured under mild conditions, MON under harsher ones (higher speed, heated mixture); the gap tells you how a fuel holds up under load."},{"id":"RF-89","lv":"gb","d":6,"area":"Octane","q":"Which component has the lowest octane sensitivity?","o":["Reformate","FCC naphtha","Alkylate","Ethanol"],"a":[2],"s":1,"x":"Alkylate's RON and MON are within a point or two: saturated isoparaffins behave the same under load. Aromatics drop about 10 points from RON to MON, olefins similar, ethanol around 20."},{"id":"RF-90","lv":"gb","d":6,"area":"Octane","q":"A pool meets RON 95 but fails MON 85. Which component addition fixes MON most efficiently?","o":["More reformate","More FCC naphtha","More alkylate","More ethanol"],"a":[2],"s":1,"x":"Alkylate's MON is near its RON, so it lifts MON without wasting RON; reformate and ethanol are RON-heavy and barely move MON."},{"id":"RF-91","lv":"gb","d":3,"area":"Octane","q":"The US pump octane (R+M)/2 of 87 corresponds to roughly what RON?","o":["87","91–92","95","100"],"a":[1],"s":1,"x":"Anti-knock index is the average of RON and MON; with typical sensitivity of 8–10, AKI 87 is about RON 91–92, below Europe's RON 95 Eurosuper."},{"id":"RF-92","lv":"gb","d":4,"area":"Volatility","q":"Reid vapour pressure (RVP) is the fuel's vapour pressure measured at","o":["0 °C","37.8 °C (100 °F)","100 °C","Its boiling point"],"a":[1],"s":1,"x":"A standard test temperature that stands in for a hot fuel tank; it governs cold-start ability in winter and evaporative emissions and vapour lock in summer."},{"id":"RF-93","lv":"gb","d":4,"area":"Volatility","q":"Why is n-butane the first thing a blender adds in winter and the first to leave in summer?","o":["Its octane is poor","It is cheap, has RON 93, and an RVP of about 52 psi: volume and octane in winter, but summer RVP limits leave no room for it","It freezes in winter","It is needed for diesel in summer"],"a":[1],"s":1,"x":"Butane is the cheapest octane and volume a refinery has; its vapour pressure is what sets how much the season allows."},{"id":"RF-94","lv":"gb","d":5,"area":"Volatility","q":"Why does ethanol raise a gasoline's RVP at 5–10% even though pure ethanol's vapour pressure is low?","o":["Ethanol is lighter than gasoline","Ethanol forms a low-boiling azeotrope with light hydrocarbons, so its blending RVP at low concentration is very high","It reacts with butane","It doesn't; it lowers RVP"],"a":[1],"s":1,"x":"Ethanol's effective blending RVP at 10% is around 18–20 psi; refiners make a lower-RVP blendstock (BOB) to compensate, or use ETBE, which lowers RVP."},{"id":"RF-95","lv":"gb","d":6,"area":"Volatility","q":"Which component has the lowest vapour pressure and so leaves room for butane in the summer pool?","o":["Isomerate","Alkylate","n-Butane","Light straight-run naphtha"],"a":[1],"s":1,"x":"Alkylate's RVP is around 4–5 psi; isomerate, full of isopentane, is around 13–14 psi, which limits how much of it a summer pool can take."},{"id":"RF-96","lv":"gb","d":5,"area":"Volatility","q":"E70, the percentage evaporated at 70 °C in the distillation test, mainly governs","o":["Deposit formation","Cold starting and the risk of vapour lock","Octane","Sulphur"],"a":[1],"s":1,"x":"The front end of the distillation curve: enough light ends to start a cold engine, not so many that fuel vaporises in the lines on a hot day. EN 228 sets seasonal bands."},{"id":"RF-97","lv":"gb","d":6,"area":"Volatility","q":"The vapour lock index (VLI) used in EN 228's spring and autumn classes combines","o":["RON and MON","RVP and E70","Density and sulphur","Aromatics and olefins"],"a":[1],"s":1,"x":"VLI = 10 × RVP (kPa) + 7 × E70: a single number for hot-weather drivability during the changeover months."},{"id":"RF-98","lv":"gb","d":5,"area":"Specs","q":"EN 228's limits on aromatics and olefins are","o":["35% and 18% by volume","50% and 30%","25% and 10%","No limits"],"a":[0],"s":1,"x":"Aromatics capped at 35 vol% for emissions and deposits, olefins at 18 vol% for stability and ozone-forming reactivity; both constrain how much reformate and FCC naphtha a pool can carry."},{"id":"RF-99","lv":"gb","d":4,"area":"Specs","q":"EN 228's benzene limit is","o":["5%","1% by volume","0.1%","10%"],"a":[1],"s":1,"x":"1 vol% since 2000, as a carcinogen; the US runs an annual average of 0.62%."},{"id":"RF-100","lv":"gb","d":5,"area":"Specs","q":"EN 228's oxygen limit of 3.7% by mass corresponds to roughly how much ethanol?","o":["5%","10%","15%","20%"],"a":[1],"s":1,"x":"Ethanol is 34.7% oxygen by mass; 10% by volume gives about 3.5–3.7% oxygen, which is why E10 is the limit and the older 2.7% oxygen cap allowed E5."},{"id":"RF-101","lv":"gb","d":4,"area":"Oxygenates","q":"Ethanol's blending octane is high, but its drawbacks include","o":["Phase separation with water and about a third less energy per litre","High sulphur","Low octane","High aromatics"],"a":[0],"s":1,"x":"Ethanol absorbs water and, past its limit, the water-ethanol phase drops out of the gasoline; its energy density is about 21 MJ/L against gasoline's 32, so consumption rises."},{"id":"RF-102","lv":"gb","d":6,"area":"Oxygenates","q":"Why do European refiners favour ETBE over direct ethanol blending?","o":["ETBE is cheaper to make","ETBE carries the ethanol's renewable credit while lowering RVP and avoiding phase separation","ETBE has higher oxygen content","Ethanol is banned in Europe"],"a":[1],"s":1,"x":"Ethyl tertiary-butyl ether is made from ethanol and isobutylene; it blends like a hydrocarbon (RVP around 4 psi), with octane near 118 and no water problem."},{"id":"RF-103","lv":"gb","d":5,"area":"Oxygenates","q":"MTBE was phased out in the United States because","o":["Its octane was too low","It contaminated groundwater from leaking tanks and is persistent and foul-tasting","It raised RVP","It corroded engines"],"a":[1],"s":1,"x":"Methyl tertiary-butyl ether has RON around 118 and was the main oxygenate of the 1990s; groundwater contamination led states to ban it, and ethanol replaced it."},{"id":"RF-104","lv":"gb","d":6,"area":"Stability","q":"Gasoline's oxidation stability is tested as","o":["Flash point","Induction period: minutes before oxygen uptake begins under pressure at 100 °C, EN 228 requiring at least 360","Cloud point","Copper strip corrosion"],"a":[1],"s":1,"x":"Olefinic FCC naphtha drives the induction period down; antioxidants (phenylenediamines, hindered phenols) buy it back."},{"id":"RF-105","lv":"gb","d":7,"area":"Stability","q":"Which blendstock most needs antioxidant to meet the existent-gum limit?","o":["Alkylate","Reformate","FCC naphtha","Isomerate"],"a":[2],"s":1,"x":"Its diolefins and olefins polymerise to gum; EN 228 allows 5 mg of existent gum per 100 mL. Saturated and aromatic stocks are stable."},{"id":"RF-106","lv":"gb","d":5,"area":"Energy","q":"Which gasoline component gives the most energy per litre?","o":["Ethanol","Alkylate","Reformate","Butane"],"a":[2],"s":1,"x":"Aromatics are dense (reformate around 800 kg/m³ against alkylate's 700), and energy per litre follows density; ethanol is the poorest at about two thirds of gasoline."},{"id":"RF-107","lv":"gb","d":6,"area":"Blending","q":"Octane blends","o":["Exactly linearly by volume","Roughly linearly, with positive synergy for ethanol and aromatics in paraffinic pools and penalties in others, handled with blending octane numbers","By weight","Not at all"],"a":[1],"s":1,"x":"Blenders use component blending values fitted from pool experience rather than neat octanes; ethanol's blending RON in a paraffinic base can exceed 120."},{"id":"RF-108","lv":"gb","d":6,"area":"Blending","q":"A summer pool is at its RVP limit and short of octane. Which move helps on both counts?","o":["Add butane","Swap FCC naphtha for alkylate","Add isomerate","Add light straight-run naphtha"],"a":[1],"s":1,"x":"Alkylate adds octane at very low vapour pressure; butane and isomerate add RVP, light straight-run adds neither octane nor room."},{"id":"RF-109","lv":"gb","d":7,"area":"Molecules","q":"Rank the hydrocarbon classes by research octane at the same carbon number, highest first","o":["Aromatics, branched paraffins, olefins, naphthenes, normal paraffins","Normal paraffins, naphthenes, olefins, aromatics, branched paraffins","Olefins, normal paraffins, aromatics, naphthenes, branched paraffins","Naphthenes, aromatics, olefins, normal paraffins, branched paraffins"],"a":[0],"s":1,"x":"Rings and branching resist autoignition; long straight chains ignite easily (n-heptane is zero). Branching and aromaticity are the two routes to octane, which is what the octane units are for."},{"id":"RF-110","lv":"gb","d":5,"area":"Molecules","q":"Which two reformer products are also the feed for an aromatics (BTX) complex?","o":["Benzene and toluene","Hydrogen","Isobutane","LPG"],"a":[0],"s":1,"x":"A refinery with a petrochemical arm extracts benzene, toluene and xylenes from reformate for styrene, polyester (paraxylene) and solvents instead of burning them as gasoline."},{"id":"RF-111","lv":"db","d":3,"area":"Cetane","q":"Cetane number measures","o":["Energy content","Ignition delay: how readily the fuel self-ignites under compression","Sulphur content","Viscosity"],"a":[1],"s":1,"x":"A high cetane fuel ignites soon after injection: smoother, quieter combustion and easier cold starts. The scale runs from n-hexadecane (cetane) at 100 to heptamethylnonane at 15."},{"id":"RF-112","lv":"db","d":4,"area":"Molecules","q":"Which molecular class has the highest cetane?","o":["Aromatics","Normal (straight-chain) paraffins","Branched paraffins","Polycyclic aromatics"],"a":[1],"s":1,"x":"The opposite of octane: long straight chains ignite readily. n-Hexadecane defines 100; aromatics sit in the 20s and polyaromatics lower still."},{"id":"RF-113","lv":"db","d":5,"area":"Molecules","q":"The cetane–cold-flow trade-off in diesel blending is that","o":["High-cetane normal paraffins also have the highest cloud points, crystallising as wax in the cold","High cetane raises sulphur","Low cetane fuels freeze","Aromatics improve cold flow and cetane together"],"a":[0],"s":1,"x":"The same long straight chains that ignite well form wax crystals first; winter diesel needs isomerised or lighter paraffins, kerosene, or cold-flow additives."},{"id":"RF-114","lv":"db","d":4,"area":"Cold flow","q":"Cloud point is","o":["The temperature at which the fuel ignites","The temperature at which wax crystals first appear and the fuel turns hazy","The temperature at which it stops pouring","The flash point in winter"],"a":[1],"s":1,"x":"Below the cloud point, wax can block filters; CFPP, the cold filter plugging point, is the operational limit and EN 590's climate classes set it, class F at −20 °C."},{"id":"RF-115","lv":"db","d":5,"area":"Cold flow","q":"Cold-flow improvers work by","o":["Dissolving the wax","Modifying wax crystal growth so crystals stay small and pass filters, lowering CFPP without changing cloud point","Raising the cetane","Adding alcohol"],"a":[1],"s":1,"x":"Ethylene–vinyl acetate copolymers and similar additives co-crystallise with wax and keep crystals small; they lower CFPP and pour point but barely move the cloud point."},{"id":"RF-116","lv":"db","d":4,"area":"Cold flow","q":"The cheapest way to winterise diesel without additives is","o":["Adding FAME","Blending in kerosene, which lowers cloud point at a cost in cetane and viscosity","Adding water","Hydrotreating harder"],"a":[1],"s":1,"x":"Kerosene is lighter and lower in wax; refineries shift the diesel cut lighter for winter grades, giving up some yield and cetane."},{"id":"RF-117","lv":"db","d":5,"area":"Specs","q":"EN 590's density window is","o":["720–775 kg/m³","820–845 kg/m³","880–900 kg/m³","No limit"],"a":[1],"s":1,"x":"820–845 kg/m³ at 15 °C. It is why neat HVO, at about 780, cannot be sold as EN 590 diesel and has its own paraffinic standard, EN 15940."},{"id":"RF-118","lv":"db","d":6,"area":"Specs","q":"How much HVO can an EN 590 blend take before density falls below 820?","o":["About 10%","About 25–30%, depending on the base fuel's density","Unlimited","None"],"a":[1],"s":1,"x":"With a base at 840 and HVO at 780, about a third brings the blend to the floor; FAME, at 880, pulls the other way, so HVO and FAME together give the blender room."},{"id":"RF-119","lv":"db","d":4,"area":"Specs","q":"EN 590 limits polycyclic aromatic hydrocarbons (PAH) to","o":["2%","8% by mass","20%","No limit, only total aromatics"],"a":[1],"s":1,"x":"8 wt% of di- and tri-aromatics: the molecules that make soot. LCO is the stream that threatens the limit."},{"id":"RF-120","lv":"db","d":5,"area":"Specs","q":"Diesel lubricity is specified because","o":["Diesel engines need oil-free fuel","Removing sulphur to 10 ppm also removed the polar compounds that lubricated the pump, so ULSD needs additives or FAME to pass the HFRR test","Lubricity raises cetane","It prevents freezing"],"a":[1],"s":1,"x":"The high-frequency reciprocating rig measures wear scar; EN 590 allows 460 microns. Lubricity additives at a few hundred ppm, or 1–2% FAME, restore what deep hydrotreating took out."},{"id":"RF-121","lv":"db","d":4,"area":"Specs","q":"EN 590's flash point minimum of 55 °C matters because","o":["Lower flash point raises cetane","It classes diesel as a safer, non-volatile fuel for storage and transport; contamination with gasoline or jet drops it fast","It controls cold flow","It sets the viscosity"],"a":[1],"s":1,"x":"A few per cent of gasoline in a diesel tank can take the flash point below the limit; it is the first spec that fails on cross-contamination."},{"id":"RF-122","lv":"db","d":5,"area":"Components","q":"Light cycle oil's problem in the diesel pool is","o":["Too high a cetane","Cetane in the 20s and aromatics near 70–80%, so it fails cetane and PAH unless deeply hydrotreated or hydrocracked","Its flash point","Its colour"],"a":[1],"s":1,"x":"Severe hydrotreating saturates the aromatics and lifts cetane into the 40s at a heavy hydrogen cost; otherwise LCO is diluted sparingly or sold as fuel-oil cutter."},{"id":"RF-123","lv":"db","d":4,"area":"Components","q":"Hydrocracker diesel is prized in the pool because it is","o":["Cheap","Paraffinic: cetane in the mid-50s, almost no sulphur or aromatics","High in olefins","Heavier than the spec"],"a":[1],"s":1,"x":"The hydrocracker's saturated products lift cetane and dilute aromatics; a refinery short of cetane values it above straight-run."},{"id":"RF-124","lv":"db","d":5,"area":"Components","q":"Coker gas oil needs hydrotreating before the pool because it is","o":["Too light","Olefinic and high in sulphur and nitrogen, which also poisons downstream catalysts","Too waxy","Too high in cetane"],"a":[1],"s":1,"x":"Thermal cracking leaves olefins and heteroatoms; nitrogen in particular inhibits hydrodesulphurisation catalysts, so coker stocks are treated in their own harder service."},{"id":"RF-125","lv":"db","d":4,"area":"Renewables","q":"HVO brings to a diesel pool","o":["High aromatics","Cetane of 70–90, no sulphur, no aromatics, but low density and, if not isomerised, a high cloud point","High oxygen content","Lubricity"],"a":[1],"s":1,"x":"Fully paraffinic: the best cetane in the pool and clean combustion, with density the constraint; winter grades are isomerised to cloud points of −20 to −30 °C."},{"id":"RF-126","lv":"db","d":5,"area":"Renewables","q":"FAME brings to a diesel pool","o":["Cetane around 50–55, excellent lubricity, higher density, but oxygen, water affinity, worse oxidation stability and poor cold flow for some feedstocks","Zero oxygen","Low density","High aromatics"],"a":[0],"s":1,"x":"Methyl esters carry 11% oxygen: a little less energy, hygroscopic, prone to oxidise into acids and deposits; palm methyl ester's CFPP is around +10 °C, rapeseed's around −10."},{"id":"RF-127","lv":"db","d":5,"area":"Renewables","q":"Why is FAME capped at 7% in EN 590 while HVO has no such cap?","o":["FAME has higher cetane","FAME is a different chemical family (esters) with oxygen, water and stability issues that engines and seals were only approved for at low blends; HVO is a hydrocarbon like the rest","HVO is cheaper","FAME is denser"],"a":[1],"s":1,"x":"HVO is paraffinic diesel: within density limits it blends freely, and neat it has its own standard; FAME's chemistry needs the blend wall."},{"id":"RF-128","lv":"db","d":6,"area":"Renewables","q":"Why does jet fuel need some aromatics, limiting HEFA SAF to a 50% blend?","o":["Aromatics raise the freeze point","Aromatics swell elastomer seals in fuel systems; fully paraffinic fuel can shrink them and cause leaks","Aromatics raise energy content","Aromatics are needed for ignition"],"a":[1],"s":1,"x":"Jet A-1 specifies 8–25% aromatics; neat HEFA has none, so blends are capped at 50% until seal-compatible fuels or synthetic aromatics are approved."},{"id":"RF-129","lv":"db","d":5,"area":"Cetane","q":"Cetane improvers such as 2-ethylhexyl nitrate work by","o":["Adding paraffins","Decomposing early in the compression stroke into radicals that trigger ignition, adding 3–8 cetane numbers at a few hundred ppm","Lowering density","Removing aromatics"],"a":[1],"s":1,"x":"2-EHN and di-tert-butyl peroxide are the standard improvers; they lift cetane number but not cetane index, which is calculated from density and distillation."},{"id":"RF-130","lv":"db","d":6,"area":"Cetane","q":"Cetane index differs from cetane number in that it is","o":["Measured in a different engine","Calculated from density and distillation temperatures, so it misses the effect of improvers and biofuels","Always lower","Only used in the US"],"a":[1],"s":1,"x":"ISO 4264 estimates ignition quality from physical properties, cheaply and without an engine; EN 590 requires both, with the index at 46 minimum."},{"id":"RF-131","lv":"db","d":5,"area":"Specs","q":"EN 590's T95 limit of 360 °C controls","o":["Cold flow","The heavy tail: fuel that doesn't vaporise and burn cleanly, making deposits and smoke","Lubricity","Water content"],"a":[1],"s":1,"x":"The back end of the distillation curve; heavy gas oil and LCO push it up, kerosene pulls it down."},{"id":"RF-132","lv":"db","d":4,"area":"Energy","q":"Energy per litre, highest first","o":["Diesel, HVO, FAME","FAME, HVO, diesel","HVO, FAME, diesel","All equal"],"a":[0],"s":1,"x":"About 35.8, 34.4 and 33 MJ/L: HVO's low density and FAME's oxygen both cost a few per cent in fuel economy."},{"id":"RF-133","lv":"db","d":6,"area":"Stability","q":"Why does a FAME blend's cold-flow additive response disappoint?","o":["FAME raises the cloud point of the base","Saturated methyl esters crystallise in their own structures that the hydrocarbon wax modifiers don't control well","FAME dissolves the additive","FAME lowers cetane"],"a":[1],"s":1,"x":"Ester crystals need their own additive chemistry; a B7 that was fine with the base fuel's additive can fail CFPP, which is why winter FAME is kept low or specified by feedstock."},{"id":"RF-134","lv":"db","d":5,"area":"Specs","q":"Diesel conductivity additive is dosed because","o":["Low-sulphur diesel barely conducts electricity, so static charge builds on fast loading and could spark; a few ppm of additive bleeds it off","It improves cetane","It lowers cloud point","It prevents microbes"],"a":[0],"s":1,"x":"Ultra-low-sulphur fuels lost the polar compounds that conducted charge; EN 590 requires conductivity for safe handling."},{"id":"RF-135","lv":"db","d":6,"area":"Blending","q":"A pool is at cetane 50 with PAH at the limit and needs 51. Which addition works without breaching PAH?","o":["More LCO","More HVO","More kerosene","More straight-run heavy gas oil"],"a":[1],"s":1,"x":"HVO lifts cetane sharply and dilutes aromatics; LCO adds PAH, kerosene lowers cetane, heavy gas oil adds both aromatics and T95."},{"id":"RF-136","lv":"db","d":7,"area":"Components","q":"Which three properties does kerosene blending into diesel improve or worsen? Pick the two it worsens","o":["Cloud point","Cetane number","Viscosity (lubricity)","Flash point"],"a":[1,2],"s":2,"x":"Kerosene lowers cloud point and flash point; it also lowers cetane (kerosene around 42–45) and viscosity, which hurts lubricity. The cold-flow gain is paid for in cetane and pump wear."},{"id":"RF-137","lv":"gb","d":6,"area":"Blending","q":"Which two components raise a gasoline pool's RVP most?","o":["n-Butane","Alkylate","Isomerate","Reformate"],"a":[0,2],"s":2,"x":"Butane at around 52 psi and isomerate, rich in isopentane, at 13–14; alkylate and reformate are the low-pressure components that make room."},{"id":"RF-138","lv":"gb","d":5,"area":"Octane","q":"Which two have high octane sensitivity (RON far above MON)?","o":["Alkylate","Reformate","FCC naphtha","Isomerate"],"a":[1,2],"s":2,"x":"Aromatics and olefins lose about 10 points from RON to MON; saturated isoparaffins in alkylate and isomerate lose only a point or two."},{"id":"RF-139","lv":"db","d":5,"area":"Renewables","q":"Which two are fully paraffinic diesels with cetane above 70?","o":["HVO","FAME","GTL diesel","LCO"],"a":[0,2],"s":2,"x":"Hydrotreated vegetable oil and gas-to-liquids diesel are both synthetic paraffins: cetane 70–80, no aromatics, no sulphur, low density."}];
